import logging.config, multiprocessing, queue, signal

RELOAD = multiprocessing.Event()

def _on_hup(signum, frame):
    RELOAD.set()                                     # never do real work inside a signal handler

signal.signal(signal.SIGHUP, _on_hup)
signal.signal(signal.SIGTERM, lambda *_: SHUTDOWN.set())

