from fastapi import Depends, FastAPI

admin = FastAPI()                                       # separate app, separate port, not the public API

@admin.get('/routes/{route}/status')
def status(route: str, _: None = Depends(require_ops_token)) -> dict:
    return routes[route].snapshot()

@admin.post('/routes/{route}/suspend')
def suspend(route: str, reason: str, _: None = Depends(require_ops_token)) -> dict:
    return {'applied': routes[route].suspend(reason)}    # drain in-flight work, then report
